import pytest

from approve import approver


def test_exactly_500_needs_manager():
    assert approver(50000) == "manager"


def test_exactly_5000_needs_vp():
    assert approver(500000) == "vp"


def test_just_under_500_needs_no_one():
    assert approver(49999) is None


# 500001 cents = $5,000.01, which crosses the VP threshold too.
def test_just_over_500_but_also_over_5000_needs_vp():
    assert approver(500001) == "vp"


@pytest.mark.parametrize(
    ("total_cents", "expected"),
    [
        # Around $500.00 threshold
        (49999, None),      # one cent below -> no approval needed
        (50000, "manager"),  # exactly $500.00 -> manager
        (50001, "manager"),  # one cent above -> manager
        # Around $5000.00 threshold
        (499999, "manager"),  # one cent below -> still manager
        (500000, "vp"),       # exactly $5000.00 -> vp
        (500001, "vp"),       # one cent above -> vp
    ],
    ids=[
        "1c-under-500", "exact-500", "1c-over-500",
        "1c-under-5000", "exact-5000", "1c-over-5000",
    ],
)
def test_threshold_boundaries(total_cents, expected):
    assert approver(total_cents) == expected
